#include <iostream>
#include <vector>
#include <deque>

using namespace std;

struct Child {
    int cryVolume;
    int exitVolume;
    int confidence;
    int index;
};

int main() {
    int n;
    cin >> n;

    vector<Child> children(n);
    for (int i = 0; i < n; i++) {
        cin >> children[i].cryVolume >> children[i].exitVolume >> children[i].confidence;
        children[i].index = i + 1;
    }

    deque<int> queue;
    vector<bool> treated(n, false);

    int front = 0;
    while (front < n) {
        // Treat the first child in the queue
        int currentIndex = front;
        int cry = children[currentIndex].cryVolume;
        treated[currentIndex] = true;
        queue.push_back(children[currentIndex].index);

        // Reduce confidence of the remaining children
        for (int i = currentIndex + 1; i < n; i++) {
            children[i].confidence -= (cry - (i - currentIndex));
            if (children[i].confidence < 0 && !treated[i]) {
                cry = children[i].exitVolume;
                // Reduce confidence of the children after i-th child
                for (int j = i + 1; j < n; j++) {
                    children[j].confidence -= cry;
                }
            }
        }
        front++;

        // Rerun the loop until we find a child with non-negative confidence
        while (front < n && treated[front]) front++;
    }

    cout << queue.size() << endl;
    for (int number : queue) {
        cout << number << " ";
    }
    cout << endl;

    return 0;
}

