    for (int i = 0; i < n; ++i) {
        line.push_back(i);
    }

    vector<int> result;

    while (!line.empty()) {
        int currentIndex = line.front();
        line.pop_front();

        int cryVolume = children[currentIndex].cryVolume;
        int numChildren = line.size();

        // Reduce confidence of children in line
        for (int i = 0; i < numChildren; ++i) {
            int childIndex = line[i];
            children[childIndex].confidence -= (cryVolume - i);
            // Check if the child cries and exits
