                line.erase(line.begin() + i);  // Remove this child from the line
                --i;  // Stay at the same index since we removed one
            }
        }

        // Treat the current child
        result.push_back(children[currentIndex].index);
    }

    cout << result.size() << endl;
    for (int i = 0; i < result.size(); ++i) {
