double minTime(double x1, double y1, double x2, double y2, double v, double t, pair<double, double> wind1, pair<double, double> wind2) {
    double d = distance(x1, y1, x2, y2);

    double v1x = wind1.first;
    double v1y = wind1.second;
    double v2x = wind2.first;
    double v2y = wind2.second;

    double minTime = d / v; // Basic straight-flight time without wind

    double dx1 = v1x * t;
    double dy1 = v1y * t;

    double x1t = x1 + dx1;
    double y1t = y1 + dy1;

    double d1 = distance(x1t, y1t, x2, y2);
    double time1 = t + d1 / v;

    minTime = min(minTime, time1);

    double d2 = distance(x1, y1, x2, y2);
    double vRel = sqrt(pow(v2x, 2) + pow(v2y, 2));
    double t2 = d2 / (v - vRel);

    if (vRel < v) {
        minTime = min(minTime, t2);
    }

    return minTime;
