const int MOD = 1e9 + 7;

long long count_good_numbers(int n, int k, const vector<int>& a, const vector<int>& b) {
    int m = n / k;
    long long total_count = 1;

    for (int i = 0; i < m; i++) {
        long long count = 0;
        int base = a[i];
        int bad_digit = b[i];

        for (int j = 0; j < (1 << k); j++) {
            bool valid = true;
            int digit_count = 0;

            for (int pos = 0; pos < k; pos++) {
                if (j & (1 << pos)) {
                    digit_count++;
                    if (pos == 0 && ((j >> pos) & 1) == bad_digit) {
                        valid = false;
                        break;
                    }
                }
            }

            if (valid && digit_count > 0) {
