                for (int pos = 0; pos < k; pos++) {
                    if (j & (1 << pos)) {
                        number = number * 10 + ((j >> pos) & 1);
                    }
                }
                if (number % base == 0) {
                    count++;
                }
            }
        }

        total_count = (total_count * count) % MOD;
    }

    return total_count;
}

