// Function to compute x^y mod m
long long modExp(long long x, long long y, int m) {
    long long res = 1;
    x = x % m; // Update x if it is more than or equal to m
    while (y > 0) {
        // If y is odd, multiply x with the result
        if (y & 1)
            res = (res * x) % m;
        // y must be even now
        y = y >> 1; // y = y / 2
        x = (x * x) % m; // Change x to x^2
    }
    return res;
}

