#include <bits/stdc++.h>
using namespace std;

struct Line {
    int start, end, y; // for vertical lines: x == start, y1 == y, y2 will be in the end separate
    bool isVertical;

    Line(int x1, int y1, int x2, int y2) {
        if (x1 == x2) {
            isVertical = true;
            start = min(y1, y2);
            end = max(y1, y2);
            y = x1;
        } else {
            isVertical = false;
            start = min(x1, x2);
            end = max(x1, x2);
            y = y1;
        }
    }
};

int main() {
    int n;
    cin >> n;
    vector<Line> lines;

    for (int i = 0; i < n; ++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        lines.emplace_back(x1, y1, x2, y2);
    }

    set<pair<int, int>> paintedCells;

    for (const auto& line : lines) {
        if (line.isVertical) {
            for (int i = line.start; i <= line.end; ++i) {
                paintedCells.insert({line.y, i});
            }
        } else {
            for (int i = line.start; i <= line.end; ++i) {
                paintedCells.insert({i, line.y});
            }
        }
    }

    cout << paintedCells.size() << endl;
    return 0;
}

