using namespace std;

struct Event {
    int x, y1, y2, type;
    Event(int _x, int _y1, int _y2, int _type) : x(_x), y1(_y1), y2(_y2), type(_type) {}
    bool operator<(const Event &e) const {
        return x < e.x || (x == e.x && type < e.type);
    }
};

int main() {
    int n;
    cin >> n;

    vector<Event> events;

    for (int i = 0; i < n; i++) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        if (x1 > x2) swap(x1, x2);
        if (y1 > y2) swap(y1, y2);
        events.emplace_back(x1, y1, y2, 1);
        events.emplace_back(x2, y1, y2, -1);
    }

    sort(events.begin(), events.end());

    set<pair<int, int>> active;
    long long total_area = 0;
    int last_x = events[0].x;

    for (const auto &event : events) {
        total_area += (event.x - last_x) * active.size();
        if (event.type == 1) {
            active.insert({event.y1, event.y2});
        } else {
            active.erase({event.y1, event.y2});
        }

        vector<pair<int, int>> merged;
        for (const auto &interval : active) {
            if (merged.empty() || merged.back().second < interval.first) {
                merged.push_back(interval);
            } else {
                merged.back().second = max(merged.back().second, interval.second);
            }
        }

        active.clear();
        for (const auto &interval : merged) {
            active.insert(interval);
        }

        last_x = event.x;
    }

    cout << total_area << endl;
    return 0;
}

