#include <algorithm>
#include <map>

using namespace std;

struct Friend {
    char gender;
    int start, end;
};

int main() {
    int n;
    cin >> n;
    vector<Friend> friends(n);
    for (int i = 0; i < n; ++i) {
        cin >> friends[i].gender >> friends[i].start >> friends[i].end;
    }

    int max_count = 0;

    // Check each day from 1 to 366
    for (int day = 1; day <= 366; ++day) {
        int male_count = 0;
        int female_count = 0;

        for (const auto& f : friends) {
            if (f.start <= day && f.end >= day) {
                if (f.gender == 'M') {
                    male_count++;
                } else {
                    female_count++;
                }
            }
        }

        // The number of pairs we can have is limited by the minimum of male and female
        max_count = max(max_count, 2 * min(male_count, female_count));
    }

    cout << max_count << endl;
    return 0;
}

