#include <iostream>
#include <vector>
#include <string>

using namespace std;

struct Block {
    int length;
    char character;
};

int main() {
    int n, m;
    cin >> n >> m;

    vector<Block> t(n), s(m);

    for (int i = 0; i < n; i++) {
        char dash;
        cin >> t[i].length >> dash >> t[i].character;
    }

    for (int i = 0; i < m; i++) {
        char dash;
        cin >> s[i].length >> dash >> s[i].character;
    }

    int occurrences = 0;
    for (int start = 0; start <= n - m; start++) {
        bool match = true;
        for (int j = 0; j < m; j++) {
            if (t[start + j].character != s[j].character) {
                match = false;
                break;
            }
            if (t[start + j].length < s[j].length) {
                match = false;
                break;
            }
        }
        if (match) {
            int min_length = 0;
            for (int j = 0; j < m; j++) {
                min_length += s[j].length;
            }
            occurrences++;
        }
    }

    cout << occurrences << endl;

    return 0;
}

