#include <iostream>
#include <vector>
#include <string>
#include <tuple>

using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<pair<int, char>> t(n), s(m);

    for (int i = 0; i < n; ++i) {
        int len;
        char ch;
        cin >> len; // li
        cin.ignore(); // ignore '-'
        cin >> ch; // ci
        t[i] = {len, ch};
    }

    for (int i = 0; i < m; ++i) {
        int len;
        char ch;
        cin >> len; // li
        cin.ignore(); // ignore '-'
        cin >> ch; // ci
        s[i] = {len, ch};
    }

    int count = 0;

    for (int start = 0; start < n; ++start) {
        int i = start, j = 0;
        long long total = 0;

        while (i < n && j < m) {
            if (t[i].second != s[j].second) {
                break;
            }

            int min_count = min(t[i].first, s[j].first);
            total += min_count;
            t[i].first -= min_count;
            s[j].first -= min_count;

            if (s[j].first == 0) {
                j++;
            }
            if (t[i].first == 0) {
                i++;
            }
        }

        if (j == m) {
            count++;
        }
    }

    cout << count << "\n";
    return 0;
}

