bool solveRebus(const string& input) {
    string equation = input;
    replace(equation.begin(), equation.end(), '-', ' ');
    replace(equation.begin(), equation.end(), '+', ' ');
    replace(equation.begin(), equation.end(), '=', ' ');

    istringstream iss(equation);
    vector<int> nums;
    int target;
    string token;
    while (iss >> token) {
        if (token == "?") {
            nums.push_back(-1); // placeholder for ?
        } else {
            if (target == 0) {
                target = stoi(token);
            } else {
                nums.push_back(stoi(token));
            }
        }
    }

    int countQMarks = count(nums.begin(), nums.end(), -1);
    int numCount = nums.size() - countQMarks;

    int currentSum = 0;
    for (int num : nums) {
        if (num != -1) currentSum += num;
    }

    int totalNeeded = target - currentSum;

    // Using ? as +1, we need totalNeeded >= count of ? and importantly it should be positive
    if (totalNeeded < countQMarks || totalNeeded <= 0) {
        cout << "Impossible" << endl;
        return false;
    }

    // Fill the ? with appropriate values
    for (int& num : nums) {
        if (num == -1) {
            num = 1; // We place 1 initially
            totalNeeded -= 1;
        }
    }

    // Adjust the last ? with the remaining totalNeeded
