double calculate_min_distance(vector<Bottle>& bottles, double ax, double ay, double bx, double by, double tx, double ty) {
    int n = bottles.size();
    vector<double> dist_from_a(n);
    vector<double> dist_from_b(n);

    for (int i = 0; i < n; ++i) {
        dist_from_a[i] = distance(ax, ay, bottles[i].x, bottles[i].y) + distance(bottles[i].x, bottles[i].y, tx, ty);
        dist_from_b[i] = distance(bx, by, bottles[i].x, bottles[i].y) + distance(bottles[i].x, bottles[i].y, tx, ty);
    }

    vector<double> dp(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        dp[i + 1] = dp[i] + dist_from_a[i];
        for (int j = 0; j <= i; ++j) {
            dp[i + 1] = min(dp[i + 1], dp[j] + dist_from_b[i] + (i - j) * dist_from_a[j]);
        }
    }

