void findVertexCover(int n, int m, const vector<pair<int, int>>& edges) {
    vector<int> coverA, coverB;
    vector<int> color(n + 1, -1); // -1 = uncolored, 0 = color A, 1 = color B

    for (const auto& edge : edges) {
        int u = edge.first;
        int v = edge.second;

        if (color[u] == -1 && color[v] == -1) {
            color[u] = 0; // Color u with color A
            color[v] = 1; // Color v with color B
        } else if (color[u] == -1) {
            color[u] = 1 - color[v]; // Assign the opposite color
        } else if (color[v] == -1) {
            color[v] = 1 - color[u]; // Assign the opposite color
        } else if (color[u] == color[v]) {
            cout << "-1\n";
            return;
        }
    }

    for (int i = 1; i <= n; ++i) {
        if (color[i] == 0) {
            coverA.push_back(i);
        } else if (color[i] == 1) {
            coverB.push_back(i);
        }
    }

    cout << coverA.size() << "\n";
    for (int v : coverA) {
        cout << v << " ";
    }
    cout << "\n";

    cout << coverB.size() << "\n";
    for (int v : coverB) {
        cout << v << " ";
    }
    cout << "\n";
}

