#include <string>
using namespace std;

int main() {
    int n, d;
    cin >> n >> d;
    string schedule[d];
    for (int i = 0; i < d; i++) {
        cin >> schedule[i];
    }

    int maxConsecutiveDays = 0, currentStreak = 0;

    for (int i = 0; i < d; i++) {
        bool allPresent = true;
        for (int j = 0; j < n; j++) {
            if (schedule[i][j] == '1') {
                allPresent = false;
                break;
            }
        }

        if (allPresent) {
            currentStreak++;
        } else {
            maxConsecutiveDays = max(maxConsecutiveDays, currentStreak);
            currentStreak = 0;
        }
    }

    maxConsecutiveDays = max(maxConsecutiveDays, currentStreak);

    cout << maxConsecutiveDays << endl;

    return 0;
}

