                if (c == '0') {
                    all_present = false;
                    break;
                }
            }
            if (!all_present) {
                current_wins++;
            } else {
                // All opponents present
                max_consecutive_wins = std::max(max_consecutive_wins, current_wins);
                current_wins = 0;
            }
        }
    }

    max_consecutive_wins = std::max(max_consecutive_wins, current_wins);
    std::cout << max_consecutive_wins << std::endl;

    return 0;
}

