    // The n-th even-length palindrome can be found by taking the prefix
    // of n and creating a palindrome by mirroring it.
    // Even-length palindromes with n digits can be generated using the first n digits.

    // Convert n to an integer
    long long k = stoll(n);

    // The k-th even-length palindrome is formed by the digits of k mirrored.
    // For example, for k=1, the result is "11" (1 mirrored becomes 11),
    // for k=10, it is "1001" (10 mirrored becomes 1001), etc.

    // We need to create a string representation of k
    std::string prefix = std::to_string(k);
    std::string palindrome = prefix;

    // Mirror the prefix
    std::reverse(prefix.begin(), prefix.end());

    // Combine to form the palindrome
    palindrome += prefix;

    std::cout << palindrome << std::endl;
    return 0;
}

