    for (int i = 0; i < n; ++i) {
        current_parents.insert(a[i]);
    }

    vector<int> result = a;
    int changes = 0;
    int root = -1;

    for (int i = 1; i <= n; ++i) {
        if (current_parents.find(i) == current_parents.end()) {
            result[changes] = i;
            changes++;
        } else if (i == result[i - 1]) {
            root = i; // find root
        }
    }

    if (root == -1) {
        root = result[0];
    }

    result[root - 1] = root; // the root must point to itself
    for (int i = changes; i < n; ++i) {
        if (result[i] != result[i - 1]) {
            result[i] = root;
        }
    }

    cout << changes << endl;
    for (int i = 0; i < n; ++i) {
        cout << result[i] << " ";
    }
