#include <iostream>
#include <algorithm>

int main() {
    int x, y;
    std::cin >> x >> y;

    int total_seconds = 0;

    while (x > y) {
        // Reduce the length of the side x as much as possible while maintaining the triangle property
        if (x - 1 > y) {
            // Calculate how many steps to reach from x to y
            int step = std::min(x - 1, x - y);
            total_seconds += step;
            x -= step;
        } else {
            total_seconds += (x - y);
            x = y;
        }
    }

    std::cout << total_seconds << std::endl;
    return 0;
}

