bool isVowel(char c) {
    return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u' || c == 'y';
}

int countSyllables(const string& line) {
    int syllables = 0;
    stringstream ss(line);
    string word;

    while (ss >> word) {
        bool hasVowel = false;
        for (char c : word) {
            if (isVowel(c)) {
                hasVowel = true;
                syllables++;
                while (isVowel(c)) {
                    if (++c == word.end()) {
                        break;
                    }
                }
            }
        }
        if (!hasVowel) {
            syllables--;  // No syllables for vowel-less words
        }
    }
    return syllables;
}

int main() {
    int n;
    cin >> n;

    vector<int> patterns(n);
    for (int i = 0; i < n; ++i) {
        cin >> patterns[i];
    }
    cin.ignore();

    bool matches = true;
    for (int i = 0; i < n; ++i) {
        string line;
        getline(cin, line);
        int syllableCount = countSyllables(line);
        if (syllableCount != patterns[i]) {
            matches = false;
            break;
        }
    }

    cout << (matches ? "YES" : "NO") << endl;
    return 0;
}

