#include <iostream>
#include <vector>
#include <unordered_set>

using namespace std;

// Function to find the minimum number of workers that could make a mistake
int findMistakes(int n, int s, const vector<int>& a) {
    int mistakes = 0;
    vector<int> superiors(n + 1, 0); // to keep track of the number of superiors reported by each worker

    // Fill the superiors array based on the reported data
    for (int i = 1; i <= n; ++i) {
        superiors[i] = a[i - 1];
    }

    // Calculate the correct number of reported superiors for each worker
    // Starting from the chief, who has no superiors
    vector<int> correctSuperiors(n + 1, -1);
    correctSuperiors[s] = 0;

    // Simulate the hierarchy using DFS or BFS
    for (int i = 1; i <= n; ++i) {
        if (i == s) continue; // the chief has no superiors

        // Use the reported superiors to calculate the correct level
        // We should have a chain of correct superiors
        int count = 0;
        int id = i;
        while (id != s) {
            count++;
            id = superiors[id]; // assuming superiors stores the immediate superior ids

            if (id == 0 || id == s) break; // 0 means no valid superior.
        }
        correctSuperiors[i] = count - 1; // The count includes the worker himself

        // If the reported and correct do not match, we have a mistake
        if (superiors[i] != correctSuperiors[i]) {
            mistakes++;
        }
    }

    return mistakes;
}

int main() {
    int n, s;
    cin >> n >> s;
    vector<int> a(n);

    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    cout << findMistakes(n, s, a) << endl;
    return 0;
}

