    vector<int> depth(n + 1, 0);
    int max_t = -1;

    for (int i = 1; i <= n; ++i) {
        set<int> seen;
        int count = 0;
        int current = i;

        while (seen.insert(current).second) {
            current = crush[current];
            count++;
            if (count >= n) break;  // Prevents infinite loop if there's a cycle
        }

        if (seen.size() < depth[i]) {
            max_t = -1;
            break;
        }

        max_t = max(max_t, count);
    }

    cout << (max_t >= 1 ? max_t : -1) << endl;

    return 0;
