int main() {
    int n;
    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
        p[i]--; // Use 0-based indexing
    }

    vector<int> b(n);
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }

    unordered_set<int> visited;
    for (int i = 0; i < n; ++i) {
        int cur = i;
        while (visited.find(cur) == visited.end()) {
            visited.insert(cur);
            cur = p[cur];
        }
    }

    // Count how many cycles are in the permutation
    int cycle_count = 0;
    vector<bool> isVisited(n, false);
    for (int i = 0; i < n; ++i) {
        if (!isVisited[i]) {
            cycle_count++;
            int cur = i;
            while (!isVisited[cur]) {
                isVisited[cur] = true;
                cur = p[cur];
            }
        }
    }

    // Check if there are reverses in b
    int count_1s = 0;
    for (int i = 0; i < n; ++i) {
        count_1s += b[i];
    }

    int changes_needed = 0;
    if (cycle_count < 2) {
