int minOperationsToPassword(int n, int m, const vector<string>& strings) {
    // Initialize the cost to move each pointer to a valid character
    vector<int> costDigit(n, m), costLower(n, m), costSymbol(n, m);

    // Define the set of valid symbols
    string validSymbols = "#*&";

    // Calculate the cost to reach a valid character for each string
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (isdigit(strings[i][j])) {
                costDigit[i] = min(costDigit[i], min(j, m - j));
            } else if (islower(strings[i][j])) {
                costLower[i] = min(costLower[i], min(j, m - j));
            } else if (validSymbols.find(strings[i][j]) != string::npos) {
                costSymbol[i] = min(costSymbol[i], min(j, m - j));
            }
        }
    }

    // Use a large number to find the minimum operations needed
    int minOperations = INT_MAX;

