vector<int> longestCommonIncreasingSubsequence(vector<int>& a, vector<int>& b) {
    int n = a.size(), m = b.size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, 0));
    vector<vector<int>> prev(n + 1, vector<int>(m + 1, -1));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            if (a[i - 1] == b[j - 1]) {
                dp[i][j] = 1;
                prev[i][j] = j - 1;
            } else {
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
                if (dp[i][j] == dp[i - 1][j]) prev[i][j] = prev[i - 1][j];
                else prev[i][j] = prev[i][j - 1];
            }
        }
    }

    int length = 0, lastIndex = -1;
    for (int j = 1; j <= m; ++j) {
        if (dp[n][j] > length) {
            length = dp[n][j];
            lastIndex = j;
        }
    }

    vector<int> lcis;
    for (int i = n, j = lastIndex; i > 0 && length > 0; ) {
        if (prev[i][j] != -1 && dp[i][j] == dp[i - 1][j]) {
            --i;
        } else if (prev[i][j] != -1 && a[i - 1] == b[j - 1]) {
            lcis.push_back(a[i - 1]);
            --length;
            --i;
            --j;
        } else {
            --j;
        }
    }
    reverse(lcis.begin(), lcis.end());
    return lcis;
}

