    void addResident(const string& residentName, int bonus) {
        residents.push_back(residentName);
        used++;
        bonuses[residentName] = bonus;

        if (type == "weapon") atk += bonus;
        else if (type == "armor") def += bonus;
        else if (type == "orb") res += bonus;
    }

    void removeResident(const string& residentName) {
