    int n;
    std::cin >> n;
    std::vector<Laptop> laptops(n);

    for (int i = 0; i < n; ++i) {
        std::cin >> laptops[i].speed >> laptops[i].ram >> laptops[i].hdd >> laptops[i].cost;
        laptops[i].index = i + 1;
    }

    std::vector<Laptop> validLaptops;

    for (const auto &laptop : laptops) {
        bool outdated = false;
        for (const auto &other : laptops) {
            if (laptop.index != other.index && isOutdated(laptop, other)) {
                outdated = true;
                break;
            }
        }
        if (!outdated) {
            validLaptops.push_back(laptop);
        }
    }

    auto cheapest = *std::min_element(validLaptops.begin(), validLaptops.end(), [](const Laptop &a, const Laptop &b) {
        return a.cost < b.cost;
    });

    std::cout << cheapest.index << std::endl;

    return 0;
}

