    return 0;
}

long long choose(int n, int r) {
    if (r > n || r < 0) return 0;
    long long num = 1, den = 1;
    for (int i = 0; i < r; ++i) {
        num *= (n - i);
        den *= (i + 1);
    }
    return num / den;
}

