    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int q;
    cin >> q;
    set<int> excluded;
    for (int i = 0; i < q; ++i) {
        int size;
        cin >> size;
        for (int j = 0; j < size; ++j) {
            int theorem;
            cin >> theorem;
            excluded.insert(theorem - 1);  // using 0-based index
        }
    }

    vector<int> included;
    for (int i = 0; i < n; ++i) {
        if (excluded.find(i) == excluded.end()) {
            included.push_back(a[i]);
        }
    }

    sort(included.begin(), included.end());

    double min_avg = 0.0, max_avg = 0.0;

    int m = included.size();

    if (m > 0) {
        // Calculate maximum average in the best case
        int count_max = min(m, k);
        for (int i = m - count_max; i < m; ++i) {
            max_avg += included[i];
        }
        max_avg /= count_max;

        // Calculate minimum average in the worst case
        int count_min = min(m, k);
        for (int i = 0; i < count_min; ++i) {
            min_avg += included[i];
        }
        min_avg /= count_min;
    }

    cout << fixed << setprecision(10) << min_avg << " " << max_avg << endl;

