using namespace std;

const int MOD = 1000000007;

long long countWays(int n, int m, int k) {
    vector<vector<long long>> dp(k + 1, vector<long long>(n + 1, 0));
    for (int h = 1; h <= n; ++h) {
        for (int w = 1; w <= m; ++w) {
            dp[1][h] = (dp[1][h] + (h - 1) * (w - 1)) % MOD;
        }
    }

    for (int move = 2; move <= k; ++move) {
        for (int h = 1; h <= n; ++h) {
            for (int w = 1; w <= m; ++w) {
                if (h > 1 && w > 1)
                    dp[move][h] = (dp[move][h] + ((h - 1) * (w - 1) % MOD) * dp[move - 1][h - 2]) % MOD) % MOD;
                if (h > 1)
                    dp[move][h] = (dp[move][h] + (w - 1) * dp[move - 1][h - 2] % MOD) % MOD;
                if (w > 1)
                    dp[move][h] = (dp[move][h] + (h - 1) * dp[move - 1][h - 2] % MOD) % MOD;
            }
        }
    }

    long long totalWays = 0;
    for (int h = 1; h <= n; ++h) {
        totalWays = (totalWays + dp[k][h]) % MOD;
    }

    return totalWays;
}

