    std::vector<std::vector<std::vector<long long>>> dp(n + 1, std::vector<std::vector<long long>>(m + 1, std::vector<long long>(k + 1, 0)));

    // Base case: 0 moves means 1 way to do nothing
    dp[0][0][0] = 1;

    // Precompute the number of ways to select rectangles
    for (int h = 1; h <= k; ++h) {
