                for (int b = 1; b < j; ++b) {
                    dp[i][j][h] = (dp[i][j][h] + dp[i][b][h - 1] * (j - b) % MOD) % MOD; // split vertically
                }
            }
        }
    }

    // Calculate final result
    long long result = 0;
    for (int h = 1; h <= k; ++h) {
        result = (result + dp[n][m][h]) % MOD;
    }

