#include <iostream>
#include <set>
#include <string>

using namespace std;

set<string> outcomes;

void dfs(string &s, int count) {
    if (count == 0) {
        int ones = 0, zeros = 0;
        for (char c : s) {
            if (c == '1') ones++;
            if (c == '0') zeros++;
        }
        if (ones > 0 && zeros > 0) {
            outcomes.insert("01");
        }
        if (ones > 1) {
            outcomes.insert("11");
        }
        if (zeros > 1) {
            outcomes.insert("00");
        }
        return;
    }
    for (char &c : s) {
        if (c == '?') {
            for (char replace : {'0', '1'}) {
                c = replace;
                dfs(s, count - 1);
            }
            c = '?';
            return;
        }
    }
}

int main() {
    string input;
    cin >> input;

    int count = 0;
    for (char c : input) {
        if (c == '?') count++;
    }

    dfs(input, count);

    for (const string &out : outcomes) {
        cout << out << endl;
    }

    return 0;
}

