#include <set>
#include <string>

using namespace std;

void generateOutcomes(const string& str, set<string>& outcomes) {
    int n = str.size();
    int count_0 = 0, count_1 = 0, count_q = 0;

    for (char c : str) {
        if (c == '0') count_0++;
        else if (c == '1') count_1++;
        else count_q++;
    }

    for (int i = 0; i <= count_q; i++) {
        for (int j = 0; j <= count_q; j++) {
            if (i + j <= count_q) {
                int f0 = count_0 + (count_q - i);
                int f1 = count_1 + (count_q - j);

                if (f0 > 0 && f1 > 0) {
                    outcomes.insert("01");
                }
                if (f0 > 0) {
                    outcomes.insert("00");
                }
                if (f1 > 0) {
                    outcomes.insert("11");
                }
            }
        }
    }
}

int main() {
    string str;
    cin >> str;

    set<string> outcomes;
    generateOutcomes(str, outcomes);

    for (const auto& outcome : outcomes) {
        cout << outcome << endl;
    }

