    for (size_t i = 0; i < s.size(); i++) {
        if (s[i] == '0' || s[i] == '1' || (s[i] == '?' && removed < 2)) {
            string next = s;
            next.erase(next.begin() + i);
            if (s[i] == '?') {
                dfs(next, removed + 1);
                next[i] = '1';
                dfs(next, removed + 1);
                next[i] = '0';
            } else {
                dfs(next, removed);
            }
        }
    }
}

