#include <iostream>
#include <set>
#include <string>
#include <vector>

using namespace std;

void generateOutcomes(const string &arrangement, set<string> &outcomes) {
    int n = arrangement.size();
    vector<char> options;

    for (char ch : arrangement) {
        if (ch == '0' || ch == '1') {
            options.push_back(ch);
        } else {
            options.push_back('0');
            options.push_back('1');
        }
    }

    int totalOptions = 1 << count(arrangement.begin(), arrangement.end(), '?');
    for (int i = 0; i < totalOptions; ++i) {
        string currentArrangement = options;
        int mask = i, idx = 0;

        for (int j = 0; j < n; ++j) {
            if (arrangement[j] == '?') {
                if (mask & 1) {
                    currentArrangement[j] = '1';
                } else {
                    currentArrangement[j] = '0';
                }
                mask >>= 1;
            }
        }

        int zeroCount = count(currentArrangement.begin(), currentArrangement.end(), '0');
        int oneCount = count(currentArrangement.begin(), currentArrangement.end(), '1');

        if (zeroCount > 0) {
            if (oneCount > 0) {
                outcomes.insert("01");
                outcomes.insert("10");
            } else {
                outcomes.insert("00");
            }
        } else {
            outcomes.insert("11");
        }
    }
}

int main() {
    string arrangement;
    cin >> arrangement;

    set<string> outcomes;
    generateOutcomes(arrangement, outcomes);

    for (const string &outcome : outcomes) {
        cout << outcome << endl;
    }

    return 0;
}

