const int MOD = 1000000009;

long long countRoutes(int n) {
    std::vector<long long> dp(n/2 + 1);
    dp[0] = 1; // Base case

    for (int i = 1; i <= n/2; ++i) {
        dp[i] = 0;
        for (int j = 0; j < i; ++j) {
            dp[i] = (dp[i] + dp[j] * dp[i - 1 - j]) % MOD;
        }
        dp[i] = (dp[i] * (2 * i + 1) % MOD) % MOD; // Counts full routes at level
    }

    return dp[n/2];
}

int main() {
    int n;
    std::cin >> n;
    std::cout << countRoutes(n) << std::endl;
    return 0;
}

