#include <iostream>
#include <vector>
#include <iomanip>
#include <cmath>
using namespace std;

double calculate_time(double a, double d, double v) {
    double t_acc = v / a; // time to reach max speed v
    double s_acc = 0.5 * a * t_acc * t_acc; // distance covered during acceleration
    if (s_acc >= d) {
        // If we can reach the destination while accelerating
        return sqrt(d / a);
    } else {
        // First accelerate to max speed, then move at max speed
        double t_const = (d - s_acc) / v; // time at max speed
        return t_acc + t_const;
    }
}

int main() {
    int n;
    double a, d;
    cin >> n >> a >> d;

    vector<pair<double, double>> trolleys(n);
    for (int i = 0; i < n; ++i) {
        cin >> trolleys[i].first >> trolleys[i].second; // ti and vi
    }

    vector<double> arrival_times(n);
    double last_time = 0;

    for (int i = 0; i < n; ++i) {
        double t_i = trolleys[i].first;
        double v_i = trolleys[i].second;

        double travel_time = calculate_time(a, d, v_i);
        double arrive_time = t_i + travel_time;

        if (arrive_time < last_time) {
            arrive_time = last_time; // cannot overtake
        }

        arrival_times[i] = arrive_time;
        last_time = arrive_time;
    }

    cout << fixed << setprecision(10);
    for (double t : arrival_times) {
        cout << t << endl;
    }

    return 0;
}

