#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

vector<vector<int>> graph;
vector<int> size;

int dfs(int node, int parent) {
    size[node] = 1;
    for (int neighbor : graph[node]) {
        if (neighbor != parent) {
            size[node] += dfs(neighbor, node);
        }
    }
    return size[node];
}

long long maxProduct(int node, int parent) {
    long long maxProd = 0;
    for (int neighbor : graph[node]) {
        if (neighbor != parent) {
            long long componentSize = size[neighbor];
            long long product = componentSize * (size[1] - componentSize);
            maxProd = max(maxProd, product);
            maxProd = max(maxProd, maxProduct(neighbor, node));
        }
    }
    return maxProd;
}

int main() {
    int n;
    cin >> n;
    graph.assign(n + 1, vector<int>());
    size.assign(n + 1, 0);

    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        graph[a].push_back(b);
        graph[b].push_back(a);
