        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    void dfs(int node, int parent) {
        subSize[node] = 1;
        vector<int> childSizes;

        for (int neighbor : graph[node]) {
            if (neighbor != parent) {
                dfs(neighbor, node);
                childSizes.push_back(subSize[neighbor]);
                subSize[node] += subSize[neighbor];
            }
        }

        int totalSize = n - subSize[node];
        for (int size : childSizes) {
            maxProduct = max(maxProduct, size * totalSize);
        }
    }

    long long getMaxProduct() {
        dfs(0, -1);
        return maxProduct;
    }

private:
    int n;
    vector<vector<int>> graph;
    vector<int> subSize;
    long long maxProduct;
