using namespace std;

int main() {
    int k;
    cin >> k;

    // The maximum cycles of length 3 (triangles) in a complete graph of size n is C(n, 3) = n*(n-1)*(n-2)/6
    // We need to find the minimum n such that C(n, 3) >= k
    int n = 3;
    while (n * (n - 1) * (n - 2) / 6 < k) {
        n++;
    }

    cout << n << endl;

    // Create a complete graph
    vector<vector<int>> graph(n, vector<int>(n, 0));
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            graph[i][j] = graph[j][i] = 1;
        }
    }

    // Given n, we can only form C(n, 3) triangles. We need to remove extra triangles if k < C(n, 3)
    int totalTriangles = n * (n - 1) * (n - 2) / 6;
    int excessTriangles = totalTriangles - k;

    for (int i = 0; excessTriangles > 0 && i < n; i++) {
        for (int j = i + 1; excessTriangles > 0 && j < n; j++) {
            for (int l = j + 1; excessTriangles > 0 && l < n; l++) {
                graph[i][j] = graph[j][i] = 0;
                graph[j][l] = graph[l][j] = 0;
                graph[i][l] = graph[l][i] = 0;
                excessTriangles--;
                if (excessTriangles == 0) break;
            }
        }
    }

    // Output the adjacency matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cout << graph[i][j];
        }
        cout << endl;
    }

