#include <vector>

int main() {
    int k;
    std::cin >> k;

    // Maximum number of triangles or cycles of length 3 that can be formed is given by nC3
    // We will start checking from n = 3 upwards until we can form at least k triangles
    int n = 3;

    while ((n * (n - 1) * (n - 2) / 6) < k) {
        n++;
    }

    // Create an empty adjacency matrix
    std::vector<std::vector<int>> adj(n, std::vector<int>(n, 0));

    // Count of triangles we can form with current `n`
    int currentTriangles = 0;

    // Adding edges between every 3 vertices to maximize the triangle count
    for (int i = 0; i < n && currentTriangles < k; i++) {
        for (int j = i + 1; j < n && currentTriangles < k; j++) {
            for (int l = j + 1; l < n && currentTriangles < k; l++) {
                // Add the edges to form a triangle
                adj[i][j] = adj[j][i] = 1;
                adj[i][l] = adj[l][i] = 1;
                adj[j][l] = adj[l][j] = 1;
                currentTriangles++;
            }
        }
    }

    // Print the number of vertices
    std::cout << n << '\n';

    // Print the adjacency matrix
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
