#include <string>

int main() {
    std::string input;
    std::cin >> input;

    std::string protocol, domain, context;

    if (input.substr(0, 4) == "http") {
        protocol = "http";
        domain = input.substr(4);
    } else {
        protocol = "ftp";
        domain = input.substr(3);
    }

    size_t pos = domain.find("ru");
    if (pos != std::string::npos && pos + 2 < domain.size()) {
        context = domain.substr(pos + 2);
        domain = domain.substr(0, pos + 2);
    }

    std::cout << protocol << "://" << domain << (context.empty() ? "" : "/" + context) << std::endl;
    return 0;
}

