#include <iostream>
#include <string>

int main() {
    std::string s;
    std::cin >> s;

    std::string protocol;
    if (s.substr(0, 4) == "http") {
        protocol = "http";
    } else {
        protocol = "ftp";
    }

    std::string domain, context;
    if (protocol == "http") {
        domain = s.substr(4);
    } else {
        domain = s.substr(3);
    }

    std::size_t pos = domain.find('r');
    if (pos != std::string::npos) {
        std::string temp = domain.substr(pos);
        domain = domain.substr(0, pos);
        context = temp;
    }

    std::string result = protocol + "://" + domain + ".ru";
    if (!context.empty()) {
        result += "/" + context;
    }

    std::cout << result << std::endl;
    return 0;
}

