#include <iostream>
#include <vector>
#include <unordered_set>
using namespace std;

vector<int> apply_permutation(const vector<int>& p, const vector<int>& q) {
    vector<int> result(p.size());
    for (int i = 0; i < p.size(); ++i) {
        result[i] = p[q[i] - 1];
    }
    return result;
}

vector<int> apply_inverse_permutation(const vector<int>& p, const vector<int>& q) {
    int n = p.size();
    vector<int> inv_q(n);
    for (int i = 0; i < n; ++i) {
        inv_q[q[i] - 1] = i + 1;
    }
    return apply_permutation(p, inv_q);
}

bool is_possible(int n, int k, const vector<int>& q, const vector<int>& s) {
    unordered_set<string> seen;
