#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>

using namespace std;

struct Angle {
    double value;
    Angle(double x, double y) {
        value = atan2(y, x) * 180 / M_PI;
        if (value < 0) value += 360;
    }
};

bool cmp(const Angle &a, const Angle &b) {
    return a.value < b.value;
}

int main() {
    int n;
    cin >> n;
    vector<Angle> angles;

    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        angles.emplace_back(x, y);
    }

    sort(angles.begin(), angles.end(), cmp);

    double max_angle = 0.0;
    for (int i = 0; i < n; i++) {
        double current_angle = angles[(i + 1) % n].value - angles[i].value;
        if (current_angle < 0) current_angle += 360;
        max_angle = max(max_angle, current_angle);
    }

    cout.precision(10);
    cout << fixed << 360 - max_angle << endl;

    return 0;
}

