long long factorial(int x) {
    long long result = 1;
    for (int i = 1; i <= x; i++)
        result *= i;
    return result;
}

long long binomial_coefficient(int n, int k) {
    if (k > n || k < 0) return 0;
    return factorial(n) / (factorial(k) * factorial(n - k));
}

