    double valid_ways = 0;

    for (int i = 0; i <= n; i++) {
        if (i > k) continue;

        int required_changes = m - (k + i);
        if (required_changes <= 0) {
            valid_ways += binomial_coefficient(n, i) * binomial_coefficient(m, m);
        }

        if (required_changes >= 0) {
            valid_ways += binomial_coefficient(n, i) * binomial_coefficient(m, required_changes);
        }
    }

