#include <iostream>
#include <iomanip>
#include <vector>

using namespace std;

double computeProbability(int n, int m, int k) {
    // dp[i][j] = the number of ways to serve i people with 10-euro and j people with 20-euro, with the given change
    vector<vector<double>> dp(n + m + 1, vector<double>(n + 1, 0));
    dp[0][0] = 1; // Base case

    for (int i = 0; i < n + m; ++i) {
        for (int j = min(i, n); j >= 0; --j) {
            if (j < n) {
                dp[i + 1][j + 1] += dp[i][j]; // A person with a 10-euro banknote
            }
            if (i - j < m) { // Only serve a person with 20-euro if we have people who can do it
                int neededChange = (i - j) + k; // Current 10-euro notes after serving j people
                if (neededChange > 0) {
                    dp[i + 1][j] += dp[i][j] * neededChange; // Serve a 20-euro person
                }
            }
        }
    }

    double totalWays = 0;
    for (int j = 0; j <= n; ++j) {
        totalWays += dp[n + m][j]; // Total ways to serve all n + m people
    }

    // If possible ways is 0, return 0 probability
    if (totalWays == 0) return 0;

    // Valid ways to serve m 20-euro without failing
    double validWays = dp[n + m][n];

    return validWays / totalWays; // Return probability
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    double probability = computeProbability(n, m, k);
    cout << fixed << setprecision(6) << probability << endl;

    return 0;
}

