        int remaining = i;
        for (int p = 2; p <= n; ++p) {
            if (remaining % p == 0) {
                int cnt = 0;
                while (remaining % p == 0) {
                    cnt++;
                    remaining /= p;
                }
                factors.push_back(cnt);
            }
            if (remaining == 1) break;
        }

        long long number = 1;
        for (int j = 0; j < factors.size(); ++j) {
            int e = factors[j];
            number *= pow(primes[j], e);
        }
        if (remaining == 1) {
