using namespace std;

const int MAX_N = 1000;
const long long LIMIT = 1e18;

vector<pair<int, int>> factorization(int n) {
    vector<pair<int, int>> factors;
    for (int i = 2; i * i <= n; ++i) {
        int count = 0;
        while (n % i == 0) {
            n /= i;
            count++;
        }
        if (count > 0) {
            factors.emplace_back(i, count);
        }
    }
    if (n > 1) {
        factors.emplace_back(n, 1);
    }
    return factors;
}

long long countDivisors(long long x) {
    long long count = 1;
    for (long long i = 2; i * i <= x; ++i) {
        if (x % i == 0) {
            int currentCount = 0;
            while (x % i == 0) {
                x /= i;
                currentCount++;
            }
            count *= (currentCount + 1);
        }
    }
    if (x > 1) {
        count *= 2;
    }
    return count;
}

void generateNumbers(int pos, long long product, const vector<int> &primes, vector<long long> &results, int &nDivisors, int maxDivisors) {
    if (pos == primes.size() || product > LIMIT) {
        return;
    }
    for (int exp = 0; exp <= maxDivisors; ++exp) {
        long long newProduct = product;
        for (int i = 0; i < exp; ++i) {
            if (newProduct > LIMIT / primes[pos]) {
                return;
            }
            newProduct *= primes[pos];
        }
        int divisorsCount = nDivisors * (exp + 1);
        if (newProduct <= LIMIT && divisorsCount <= MAX_N) {
            if (divisorsCount == nDivisors) {
                results.push_back(newProduct);
            }
            generateNumbers(pos + 1, newProduct, primes, results, divisorsCount, maxDivisors);
        } else {
            break;
        }
    }
}

