    long long result = 1;
    for (int exp : exponents) {
        result *= (exp + 1);
    }
    return result;
}

// Function to generate small primes using the Sieve of Eratosthenes
vector<int> generatePrimes(int maxn) {
    vector<bool> is_prime(maxn + 1, true);
    vector<int> primes;
    for (int i = 2; i <= maxn; ++i) {
        if (is_prime[i]) {
            primes.push_back(i);
            for (int j = i * 2; j <= maxn; j += i) {
                is_prime[j] = false;
            }
        }
    }
    return primes;
}

// Function to find the smallest integer with exactly n divisors
long long smallestWithExactlyNDivisors(int n) {
    vector<int> primes = generatePrimes(30); // 30 is a reasonable limit for small primes
    long long answer = LLONG_MAX;

    // Use a backtracking approach to explore the combinations of prime powers
    function<void(int, long long, vector<int>&)> dfs = [&](int pos, long long current, vector<int>& exponents) {
        if (current > 1e18 || countDivisors(exponents) > n) return;
        if (countDivisors(exponents) == n) {
            answer = min(answer, current);
            return;
        }
        for (int i = 0; i <= n; ++i) {
            exponents.push_back(i);
            long long newValue = current;
            for (int j = 0; j < i; ++j) {
                newValue *= primes[pos];
                if (newValue > 1e18) break; // to avoid overflow
            }
            dfs(pos + 1, newValue, exponents);
            exponents.pop_back();
        }
    };

    vector<int> exponents;
    dfs(0, 1, exponents);
    return answer;
}

int main() {
    int n;
    cin >> n;
    cout << smallestWithExactlyNDivisors(n) << endl;
