#include <cmath>
#include <map>
#include <limits.h>

using namespace std;

vector<int> primes;
map<int, int> memo;

void sieve(int max_n) {
    vector<bool> is_prime(max_n + 1, true);
    for (int i = 2; i * i <= max_n; i++) {
        if (is_prime[i]) {
            for (int j = i * i; j <= max_n; j += i) {
                is_prime[j] = false;
            }
        }
    }
    for (int i = 2; i <= max_n; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
        }
    }
}

long long count_divisors(const vector<int>& exponents) {
    long long result = 1;
    for (int exp : exponents) {
        result *= (exp + 1);
    }
    return result;
}

void find_number(int n, long long current_number, int prime_index, vector<int>& exponents) {
    if (count_divisors(exponents) == n) {
        memo[current_number] = min(memo[current_number], current_number);
        return;
    }
    if (count_divisors(exponents) > n || prime_index >= primes.size()) {
        return;
    }

    for (int i = 0; i <= 60; i++) { // Limit exponent to ensure we don't exceed 10^18
        long long next_number = current_number * pow(primes[prime_index], i);
        if (next_number > 1e18) break;

        exponents.push_back(i);
        find_number(n, next_number, prime_index + 1, exponents);
        exponents.pop_back();
    }
}

int main() {
    int n;
    cin >> n;

    sieve(1000);
    memo[LLONG_MAX] = LLONG_MAX;

    vector<int> exponents;
    find_number(n, 1, 0, exponents);

    cout << memo.begin()->first << endl;
