    for (int i = 2; i * i <= num; i++) {
        if (num % i == 0) {
            int tempCount = 0;
            while (num % i == 0) {
                num /= i;
                tempCount++;
            }
            count *= (tempCount + 1);
        }
    }
    if (num > 1) {
        count *= 2;
    }
    return count;
}

void generateFactors(vector<int>& factors, int index, int n, long long& smallest) {
