struct Segment {
    int x1, y1, x2, y2;

    Segment(int x1, int y1, int x2, int y2) : x1(x1), y1(y1), x2(x2), y2(y2) {}

    int length() const {
        return abs(x2 - x1) + abs(y2 - y1);
    }

    bool intersects(const Segment &other) const {
        if ((x1 == x2 && other.x1 == other.x2) || (y1 == y2 && other.y1 == other.y2))
            return false; // both are vertical or both are horizontal
        return ((x1 <= other.x1 && other.x1 <= x2) || (x2 <= other.x1 && other.x1 <= x1)) &&
               ((y1 <= other.y1 && other.y1 <= y2) || (y2 <= other.y1 && other.y1 <= y1));
    }
};

