    int start = graph.begin()->first;
    vector<int> route;

    // Reconstructing the route
    while (!graph.empty()) {
        route.push_back(start);
        auto it = graph.find(start);
        if (it == graph.end()) break;

        // Find a neighbor to move to
        if (!it->second.empty()) {
            int next = *it->second.begin();
            it->second.erase(next);
            graph[next].erase(start);
            start = next;
        } else {
            break;
        }

        // Remove the city if no neighbors left
        if (it->second.empty()) {
            graph.erase(it);
        }
    }

    // Output result
    cout << route.size() << endl;
    for (int city : route) {
        cout << city << " ";
