    int startY = start[1] - '1';
    int targetX = target[0] - 'a';
    int targetY = target[1] - '1';

    vector<Move> directions = {
        {0, 1, "U"}, {0, -1, "D"},
        {-1, 0, "L"}, {1, 0, "R"},
        {-1, 1, "LU"}, {1, 1, "RU"},
        {-1, -1, "LD"}, {1, -1, "RD"}
    };

    queue<pair<int, int>> q;
    unordered_map<int, unordered_map<int, pair<int, string>>> prev;
    q.push({startX, startY});
    prev[startX][startY] = {-1, ""};

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        if (x == targetX && y == targetY) break;

        for (auto& move : directions) {
            int newX = x + move.x;
            int newY = y + move.y;
            if (newX >= 0 && newY >= 0 && newX < 8 && newY < 8 && !prev[newX][newY].first) {
