    queue<Position> q;
    unordered_map<int, bool> visited;

    q.push(start);
    visited[start.x * 8 + start.y] = true;

    while (!q.empty()) {
        Position current = q.front();
        q.pop();

        if (current.x == end.x && current.y == end.y) {
            cout << current.path.length() << endl;
            cout << current.path << endl;
