            int newY = current.y + directions[i].second;

            if (newX >= 0 && newX < 8 && newY >= 0 && newY < 8) {
                int index = newX * 8 + newY;
                if (!visited[index]) {
                    visited[index] = true;
                    q.push({newX, newY, current.path + directionNames[i]});
