                conflict = true;
                break;
            }
        }
        if (!conflict) {
            for (int j = 0; j < n; j++) {
                if (i != j && lessons[i].end > lessons[j].start && lessons[i].start < lessons[j].end) {
                    conflict = true;
                    break;
                }
            }
            if (!conflict) {
                count++;
                results.push_back(lessons[i].index);
            }
        }
