    } else {
        count = (n - 2 * (x - 1)) * (m - 2 * (x - 1));
        if (count < 0) count = 0;

        if (n > 2 * (x - 1) && m > 2 * (x - 1)) {
            count += 4 * (x - 1); // sides
        }
        if ((x - 1) < n / 2 && (x - 1) < m / 2) {
            count += 4; // corners
        }
