#include <iostream>
using namespace std;

long long countSquares(int n, int m, long long x) {
    if (x > (n + m - 2) / 2) return 0;
    long long count = 0;
    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 2; ++j) {
            long long h = n - i * (x + 1);
            long long w = m - j * (x + 1);
            if (h > 0 && w > 0) count += h * w;
        }
    }
    return count;
}

int main() {
    int n, m;
    long long x;
    cin >> n >> m >> x;
    cout << countSquares(n, m, x) << endl;
    return 0;
}

