#include <utility>

using namespace std;

void performOperation(vector<int>& nums, vector<string>& operations, char op, int pos) {
    if (op == '+') {
        nums[pos - 1]++;
        nums[pos % 4]++;
        operations.push_back(string(1, op) + to_string(pos));
    } else if (op == '/') {
        nums[pos - 1] /= 2;
        nums[pos % 4] /= 2;
        operations.push_back(string(1, op) + to_string(pos));
    }
}

