    for (int i = 0; i < 4; i++) {
        cin >> nums[i];
    }

    vector<string> operations;
    for (int iteration = 0; iteration < 1000; iteration++) {
        // Check if all numbers are 1
        if (nums[0] == 1 && nums[1] == 1 && nums[2] == 1 && nums[3] == 1) {
            for (const auto& op : operations) {
                cout << op << endl;
            }
            return 0;
        }

        // Check if impossible (if any is odd)
        if ((nums[0] > 1 && nums[1] > 1 && nums[2] > 1 && nums[3] > 1) && 
            (nums[0] % 2 + nums[1] % 2 + nums[2] % 2 + nums[3] % 2 == 0)) {
