#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

bool canPlace(const vector<string> &grid, const string &word, int r, int c, bool horizontal) {
    if (horizontal) {
        if (c + word.size() > 30) return false;
        for (int i = 0; i < word.size(); ++i) {
            if (grid[r][c + i] != '.' && grid[r][c + i] != word[i]) return false;
        }
    } else {
        if (r + word.size() > 6) return false;
        for (int i = 0; i < word.size(); ++i) {
            if (grid[r + i][c] != '.' && grid[r + i][c] != word[i]) return false;
        }
    }
    return true;
}

void place(vector<string> &grid, const string &word, int r, int c, bool horizontal) {
    if (horizontal) {
        for (int i = 0; i < word.size(); ++i) {
            grid[r][c + i] = word[i];
        }
    } else {
        for (int i = 0; i < word.size(); ++i) {
            grid[r + i][c] = word[i];
        }
    }
}

bool solve(vector<string> &words, vector<string> &grid) {
    sort(words.begin(), words.end());
    do {
        for (int i = 0; i < 6; ++i) {
            for (int j = 0; j < 6; ++j) {
                fill(grid.begin(), grid.end(), string(30, '.'));
                if (canPlace(grid, words[i], 0, 0, true)) {
                    place(grid, words[i], 0, 0, true);
                    if (canPlace(grid, words[(i + 1) % 6], 1, 0, false)) {
                        place(grid, words[(i + 1) % 6], 1, 0, false);
                        if (canPlace(grid, words[(i + 2) % 6], 0, 4, true)) {
                            place(grid, words[(i + 2) % 6], 0, 4, true);
                            if (canPlace(grid, words[(i + 3) % 6], 1, 4, false)) {
                                place(grid, words[(i + 3) % 6], 1, 4, false);
                                if (canPlace(grid, words[(i + 4) % 6], 2, 1, false)) {
                                    place(grid, words[(i + 4) % 6], 2, 1, false);
                                    if (canPlace(grid, words[(i + 5) % 6], 2, 3, false)) {
                                        place(grid, words[(i + 5) % 6], 2, 3, false);
                                        return true;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    } while (next_permutation(words.begin(), words.end()));
    return false;
}

int main() {
    vector<string> words(6);
    for (int i = 0; i < 6; ++i) {
        cin >> words[i];
    }

    vector<string> grid(6, string(30, '.'));
    if (solve(words, grid)) {
        for (const auto &line : grid) {
            cout << line << endl;
        }
    } else {
        cout << "Impossible" << endl;
    }

    return 0;
}

