#include <iostream>
#include <vector>
using namespace std;

int countVisiblePairs(const vector<int>& heights) {
    int n = heights.size();
    vector<int> left(n), right(n);

    // Find visible pairs in the left direction
    for (int i = 0; i < n; i++) {
        left[i] = 1; // Each can see itself
        for (int j = 1; j < n; j++) {
            int idx = (i + j) % n;
            if (heights[idx] < heights[i]) {
                left[i]++;
            } else {
                break;
            }
        }
    }

    // Find visible pairs in the right direction
    for (int i = 0; i < n; i++) {
        right[i] = 1; // Each can see itself
        for (int j = 1; j < n; j++) {
            int idx = (i - j + n) % n;
            if (heights[idx] < heights[i]) {
                right[i]++;
            } else {
                break;
            }
        }
    }

    int totalPairs = 0;
    for (int i = 0; i < n; i++) {
        totalPairs += left[i] + right[i] - 2; // we subtract 2 because each counts itself twice
    }

    return totalPairs / 2; // Each pair was counted twice
}

int main() {
    int n;
    cin >> n;
    vector<int> heights(n);
    for (int i = 0; i < n; i++) {
        cin >> heights[i];
    }

    cout << countVisiblePairs(heights) << endl;
    return 0;
}

