#include <vector>
#include <stack>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> heights(n);
    for (int i = 0; i < n; i++) {
        cin >> heights[i];
    }

    vector<int> next(n), prev(n);
    stack<int> s;

    // Calculate next visible hill to the right
    for (int i = 0; i < n; i++) {
        while (!s.empty() && heights[s.top()] < heights[i]) {
            next[s.top()] = i;
            s.pop();
        }
        s.push(i);
    }

    while (!s.empty()) {
        next[s.top()] = n + s.top(); // wrap around
        s.pop();
    }

    // Calculate previous visible hill to the left
    for (int i = n - 1; i >= 0; i--) {
        while (!s.empty() && heights[s.top()] < heights[i]) {
            prev[s.top()] = i;
            s.pop();
        }
        s.push(i);
    }

    while (!s.empty()) {
        prev[s.top()] = -1; // no left neighbor
        s.pop();
    }

    long long totalPairs = 0;
    for (int i = 0; i < n; i++) {
        int rightVisible = next[i] - i - 1;
        int leftVisible = i - prev[i] - 1;
        totalPairs += rightVisible + leftVisible;
    }

    cout << totalPairs << endl;
    return 0;
}

