int main() {
    int n;
    cin >> n;
    vector<int> heights(n);
    for (int i = 0; i < n; ++i) {
        cin >> heights[i];
    }

    long long total_pairs = 0;
    vector<int> next_right(n), next_left(n);

    // Calculate next greater height to the right
    stack<int> s;
    for (int i = 0; i < 2 * n; ++i) {
        while (!s.empty() && heights[s.top()] < heights[i % n]) {
            int idx = s.top();
            s.pop();
            next_right[idx] = (i % n) - idx;
        }
        if (i < n) s.push(i);
    }
    while (!s.empty()) {
        int idx = s.top();
        s.pop();
        next_right[idx] = n;
    }

    // Calculate next greater height to the left
    for (int i = 2 * n - 1; i >= 0; --i) {
        while (!s.empty() && heights[s.top()] < heights[i % n]) {
            int idx = s.top();
            s.pop();
            next_left[idx] = (idx - (i % n) + n) % n;
        }
        if (i < n) s.push(i);
    }
    while (!s.empty()) {
        int idx = s.top();
        s.pop();
        next_left[idx] = n;
    }

    // Count pairs
    for (int i = 0; i < n; ++i) {
        total_pairs += (next_right[i] + next_left[i]);
    }

    cout << total_pairs / 2 << endl; // Each pair counted twice
    return 0;
}

