            if (heights[j % n] > maxHeight) {
                maxHeight = heights[j % n];
                count++;
            }
            if (j - i < 0 && heights[j % n] >= heights[i]) {
                break;
            }
        }
        rightVisible[i] = count;
    }

    // Calculate total pairs
