using namespace std;

// Function to generate all possible variations of the date by changing one digit
vector<int> generate_variations(int year) {
    vector<int> variations;
    string str_year = to_string(year);

    for (int i = 0; i < 4; ++i) {
        char original_digit = str_year[i];
        for (char digit = '0'; digit <= '9'; ++digit) {
            if (digit != original_digit) {
                str_year[i] = digit;
                // First digit cannot be '0'
                if (i == 0 && digit == '0') {
                    continue;
                }
                int new_year = stoi(str_year);
                if (new_year >= 1000 && new_year <= 2011) {
                    variations.push_back(new_year);
                }
                str_year[i] = original_digit; // Restore original digit
            }
        }
    }

    return variations;
}

int main() {
    int n;
    cin >> n;
    vector<int> years(n);

    for (int i = 0; i < n; ++i) {
        cin >> years[i];
    }

    vector<int> result(n);
    result[0] = years[0];

    for (int i = 0; i < n; ++i) {
        if (i > 0) {
            vector<int> variations = generate_variations(years[i]);
            sort(variations.begin(), variations.end());

            bool found = false;
            for (int year : variations) {
                if (year >= result[i - 1]) {
                    result[i] = year;
                    found = true;
                    break;
                }
            }

            if (!found) {
                cout << "No solution" << endl;
                return 0;
            }
        }
    }

    for (int year : result) {
        cout << year << endl;
    }

    return 0;
}

