#include <string>

int countVowels(const std::string &phrase) {
    int count = 0;
    for (char ch : phrase) {
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            count++;
        }
    }
    return count;
}

bool isHaiku(const std::string &line1, const std::string &line2, const std::string &line3) {
    return countVowels(line1) == 5 && countVowels(line2) == 7 && countVowels(line3) == 5;
}

