int countSyllables(const std::string& phrase) {
    int count = 0;
    for (char ch : phrase) {
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') {
            count++;
        }
    }
    return count;
}

