        string s;
        for (int j = 0; j < n; j++) {
            s += (i & (1 << (n - j - 1))) ? '1' : '0';
        }
        string rev_s = s;
        reverse(rev_s.begin(), rev_s.end());
        unique_strings.insert(s);
        unique_strings.insert(rev_s);
