#include <string>

using namespace std;

string generateString(int n, int idx) {
    vector<string> beads;

    // Generate all bead combinations
    for (int mask = 0; mask < (1 << n); ++mask) {
        string s = "";
        for (int j = 0; j < n; ++j) {
            s += (mask & (1 << j)) ? '1' : '0';
        }
        beads.push_back(s);
    }

    // Sort beads by their defined order
    sort(beads.begin(), beads.end());

    // Unique heaps based on reversal and color swapping
    vector<string> unique;
    for (const auto& bead : beads) {
        string rev = bead;
        reverse(rev.begin(), rev.end());
        unique.push_back(bead);
        if (find(unique.begin(), unique.end(), rev) == unique.end()) {
            unique.push_back(rev);
        }
        sort(unique.begin(), unique.end());
        unique.erase(unique(unique.begin(), unique.end()), unique.end());
    }

    // Sort unique again to get the minimum string in each heap
    sort(unique.begin(), unique.end());

    // Return the k-th string in lexicographical order if it exists
    if (idx <= 0 || idx > unique.size()) {
        return "-1";
    } else {
        return unique[idx - 1];
    }
}

