    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            char ch = grid[i][j];
            if (row_chars[i].count(ch)) { 
                to_cross_out.insert(ch); 
            } else {
                row_chars[i].insert(ch);
            }
            if (col_chars[j].count(ch)) {
                to_cross_out.insert(ch);
            } else {
                col_chars[j].insert(ch);
            }
        }
    }

    string result;
    // Collect remaining letters that are not in to_cross_out.
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
