long long expected_tosses(int n) {
    if (n == 1) return 1; // only one knight, tosses = 1
    long long sum = 0;
    for (int k = 1; k <= n; ++k) {
        sum += expected_tosses(n - (n / 2)) + expected_tosses(n / 2);
    }
    return (2 * sum + n) / n; // expected tosses as irreducible fraction
}

