    int n;
    cin >> n;

    long long num = expected_tosses(n);
    long long den = 1;

    for (int i = 1; i < n; ++i) {
        den *= 2; // 2^(n-1) ways.
    }

    num *= den;
    long long gcd_value = gcd(num, den);

    num /= gcd_value;
    den /= gcd_value;

    cout << num << "/" << den << endl;
    return 0;
}

