#include <iostream>
#include <vector>

using namespace std;

pair<long long, long long> expectedTosses(int n) {
    vector<pair<long long, long long>> dp(n + 1);
    dp[1] = {1, 1}; // E(1) = 1/1

    for (int i = 2; i <= n; ++i) {
        long long numer = 0;
        long long denom = 1;

        // Calculate expected number of tosses for i knights
        for (int k = 1; k <= i; ++k) {
            long long temp_numer = dp[k].first * denom + dp[i - k].first * denom;
            long long temp_denom = denom * 2;

            // Update the numer/denom to be a fraction
            numer = numer * temp_denom + temp_numer * denom;
            denom *= 2;
            // Reduce fraction
            long long g = __gcd(numer, denom);
            numer /= g;
            denom /= g;
        }

        dp[i] = {numer + i * denom, denom}; // E(n) = (E(k) + E(n-k)) * n/2 + n/2
    }

    // Final result for n knights
    long long g = __gcd(dp[n].first, dp[n].second);
    dp[n].first /= g;
    dp[n].second /= g;

    return dp[n];
}

int main() {
    int n;
    cin >> n;
    auto result = expectedTosses(n);
    cout << result.first << "/" << result.second << endl;
    return 0;
}

