#include <string>

using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    vector<string> results(n);
    vector<string> names(26); // To hold names from A to Z
    for (int i = 0; i < 26; ++i) {
        names[i] = string(1, 'A' + i);
    }

    string lastName = names[0];
    for (int i = 0; i < n; ++i) {
        results[i] = lastName;
        if (i < k - 1) continue; // Fill initial k-1 names

        // Check the conditions
        bool same = true;
        for (int j = i - k + 1; j <= i; ++j) {
            if (results[j] == results[i]) {
                same = false;
                break;
            }
        }

        if (same) {
            // If the last name can remain, we just proceed
            continue;
        } else {
            // Change name to a different one
            lastName = (lastName == names[0]) ? names[1] : names[0];
            results[i] = lastName;
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << results[i] << " ";
    }

    cout << endl;
    return 0;
}

