    std::vector<std::string> results(n);
    std::vector<bool> used(26, false); // To track used characters

    std::string s;
    for (int i = 0; i <= n - k; i++) {
        std::cin >> s;
        if (s == "YES") {
            // If current segment is YES, we need different names in the current window
            for (int j = 0; j < k; j++) {
                if (i + j >= n) break;
                if (used[j]) {
                    results[i + j] = std::string(1, 'A' + j) + std::string(k, 'a');
                } else {
                    results[i + j] = std::string(1, 'A' + j) + std::string(k, 'a');
                    used[j] = true;
                }
            }
        } else {
            // If current segment is NO, we need to repeat some names
            for (int j = 0; j < k; j++) {
                if (i + j >= n) break;
                if (j > 0) {
                    results[i + j] = results[i]; // Repeat the first name
                } else {
                    results[i + j] = std::string(1, 'A') + std::string(k, 'a');
                }
            }
        }
    }

    for (int i = 0; i < n; i++) {
        if (results[i].empty()) {
            results[i] = std::string(1, 'A' + (i % 26)) + std::string(k, 'a');
        }
    }

