    for (int i = 0; i <= n; ++i) {
        int currentHeight = h, currentWidth = w;
        int usedExtensions = 0;

        for (int j = 0; j < i; ++j) {
            currentHeight *= extensions[j];
        }

        while (usedExtensions < n && !canFit(currentHeight, currentWidth, a, b)) {
            if (usedExtensions < n) {
                currentWidth *= extensions[usedExtensions];
                usedExtensions++;
            }
        }
        if (canFit(currentHeight, currentWidth, a, b)) {
            minExtensions = min(minExtensions, i + usedExtensions);
        }
