#include <iostream>
#include <vector>
#include <algorithm>
#include <map>
#include <cmath>
using namespace std;

bool isPoisson(const vector<int>& values, int population) {
    int n = values.size();
    double mean = 0.0;
    for (int val : values) {
        mean += (val + population);
    }
    mean /= n;

    vector<int> count(10 * population + 1, 0);
    for (int val : values) {
        count[val + population]++;
    }

    double poisson_prob[10 * population + 1];
    for (int i = 0; i <= 10 * population; i++) {
        poisson_prob[i] = exp(-mean) * pow(mean, i) / tgamma(i + 1);
    }

    double chi_square = 0.0;
    for (int i = 0; i <= 10 * population; i++) {
        if (count[i] > 0) {
            chi_square += (count[i] - n * poisson_prob[i]) * (count[i] - n * poisson_prob[i]) / (n * poisson_prob[i]);
        }
    }

    return chi_square < 11.0705; // chi-squared value with 9 degrees of freedom for alpha = 0.05
}

bool isUniform(const vector<int>& values) {
    int min_val = *min_element(values.begin(), values.end());
    int max_val = *max_element(values.begin(), values.end());
    int expectedCount = max_val - min_val + 1;
    if (expectedCount != values.size()) return false;

    map<int, int> freq;
    for (int val : values) {
        freq[val]++;
    }

    return all_of(freq.begin(), freq.end(), [&](const pair<int, int>& p) {
        return p.second == 1;
    });
}

int main() {
    int n, population;
