using namespace std;

// Function to determine if the distribution is Poisson
bool isPoisson(const vector<int>& responses, int population) {
    int n = responses.size();
    map<int, int> counts;
    for (int x : responses) {
        counts[x + population]++;
    }

    double lambda = (double) accumulate(responses.begin(), responses.end(), 0) / n;
    for (const auto& [value, count] : counts) {
        double expected = (pow(lambda, value) * exp(-lambda)) / factorial(value);
        if (expected < 1e-5) expected = 0.0;

        if (abs(count - expected * n) > 1) return false;
    }
    return true;
}

// Factorial function
long long factorial(int k) {
    if (k == 0) return 1;
    long long result = 1;
    for (int i = 1; i <= k; i++) result *= i;
    return result;
}

// Function to determine if the responses are from Uniform distribution
bool isUniform(const vector<int>& responses, int population) {
    int n = responses.size();
    int minVal = *min_element(responses.begin(), responses.end());
    int maxVal = *max_element(responses.begin(), responses.end());

    // Uniform distribution should have all counts between min and max
    if (maxVal - minVal + 1 != n) return false;

    vector<int> count(maxVal - minVal + 1, 0);
    for (int x : responses) {
        count[x - minVal]++;
    }

    for (int c : count) {
        if (c != 1) return false;
    }
    return true;
}

