    int n, k;
    cin >> n >> k;

    vector<int> dishes;
    for (int i = 1; i <= n; ++i) {
        dishes.push_back(i);
    }

    set<pair<int,int>> possible_pairs;
    for (int i = 1; i <= k; ++i) {
        for (int j = i + 1; j <= k; ++j) {
            possible_pairs.insert({i, j});
        }
    }

    for (int i = 0; i < 60; ++i) {
        int x = dishes[i % n], y = dishes[(i + 1) % n];
        cout << "1 " << x << " " << y << endl;
        cout.flush();

        string response;
        cin >> response;

        if (response == "TAK") {
            possible_pairs.erase({x, y});
        } else {
            possible_pairs.erase({y, x});
        }

        if (possible_pairs.size() == 1) {
            auto it = possible_pairs.begin();
            cout << "2 " << it->first << " " << it->second << endl;
            cout.flush();
            return 0;
        }
    }

    return 0;
}

