#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;

    // Cases where it's impossible to cover with cycles
    if (n == 3) {
        cout << "2\n3 1 2 3\n3 1 2 3\n";
        return 0;
    }
    if (n == 4) {
        cout << "3\n4 1 2 3 4\n4 1 2 3 4\n4 1 2 3 4\n";
        return 0;
    }
    if (n == 5) {
        cout << "6\n4 1 2 3 4\n4 1 2 5 4\n4 1 3 5 2\n4 2 3 5 4\n4 1 3 2 5\n4 1 2 4 5\n";
        return 0;
    }
    if (n % 2 == 1) {
        cout << "-1\n";
        return 0;
    }

    // Construct the cycles
    vector<vector<int>> cycles;
    for (int i = 1; i <= n; i += 2) {
        cycles.push_back({4, i, i + 1, (i % n) + 1, (i + 1) % n + 1});
    }

    if (n % 4 == 0) {
        for (int i = 1; i <= n; i += 4) {
            cycles.push_back({3, i, i + 1, i + 2});
            cycles.push_back({3, i + 1, i + 2, i + 3});
        }
    }
    else {
        for (int i = 1; i <= n; i += 4) {
            cycles.push_back({3, i, i + 1, i + 2});
            cycles.push_back({3, i, i + 2, i + 3});
            cycles.push_back({3, i + 1, i + 2, i + 3});
        }
    }

    // Output the cycle results
    cout << cycles.size() << "\n";
    for (const auto& cycle : cycles) {
        cout << cycle.size();
        for (int vertex : cycle) {
            cout << " " << vertex;
        }
        cout << "\n";
    }

    return 0;
}

