vector<vector<int>> graph;
vector<bool> visited;
double expected_length = 0.0;

void dfs(int city, int distance) {
    visited[city] = true;
    vector<int> unvisited_neighbors;

    for (int neighbor : graph[city]) {
        if (!visited[neighbor]) {
            unvisited_neighbors.push_back(neighbor);
        }
    }

    int num_neighbors = unvisited_neighbors.size();
    if (num_neighbors == 0) {
        return;
    }

    double increment = static_cast<double>(distance + 1) / num_neighbors;
    expected_length += increment;

    for (int neighbor : unvisited_neighbors) {
        dfs(neighbor, distance + 1);
    }
}

